<?php

declare(strict_types=1);

/**
 * Throwaway generator for the three TieBreakerRows fixtures (D13 to-many child tie-breaker task) — same mechanism
 * as generate-fixture-models.php / generate-conflict-row-models.php, scoped to the classes this change adds, since
 * they are deliberately NOT part of IntegrationTestCase::FIXTURE_ENTITY_CLASSES (see TieBreakerParent's own
 * docblock for why). Run after changing any of the three fixture entities:
 * php tests/Integration/generate-tiebreaker-row-models.php
 *
 * CAVEAT — the OneToMany side is NOT regenerated by this script and must be re-added by hand afterwards:
 * DatabaseModel::getOneToManyRelationsShips() resolves the inverse (to-many) side of a FK through
 * EntityModelGeneratorService::getAllEntityClasses(), which only scans the framework's and the consuming app's
 * src/Domain — never tests/. A fixture-to-fixture OneToMany (TieBreakerParent::$tieBreakerChildren,
 * TieBreakerChild::$tieBreakerGrandchildren) is therefore never auto-detected here; this script only ever
 * (re)generates the ManyToOne side. After running it, re-apply the two `#[ORM\OneToMany(...)]` blocks this task
 * added by hand to DBTieBreakerParentModel.php / DBTieBreakerChildModel.php (see the comments there for the exact
 * shape, lifted byte-for-byte from DatabaseModel.php's own template).
 */

use DDD\Domain\Base\Repo\DB\Database\DatabaseModel;

require __DIR__ . '/bootstrap.php';

(new ReflectionProperty(\DDD\Domain\Base\Entities\LazyLoad\LazyLoadRepo::class, 'defaultRepoType'))
    ->setValue(null, \DDD\Domain\Base\Entities\LazyLoad\LazyLoadRepo::DB);

// Order matters only for readability here — DatabaseModel::fromEntityClass() resolves FK/OneToMany relationships
// by scanning ALL registered entities (EntityModelGeneratorService::getDatabaseModels()), not by generation order.
$classes = [
    \DDD\Tests\Integration\Fixtures\Entities\TieBreakerRows\TieBreakerParent::class,
    \DDD\Tests\Integration\Fixtures\Entities\TieBreakerRows\TieBreakerChild::class,
    \DDD\Tests\Integration\Fixtures\Entities\TieBreakerRows\TieBreakerGrandchild::class,
];

foreach ($classes as $fixtureEntityClass) {
    $databaseModel = DatabaseModel::fromEntityClass($fixtureEntityClass);
    $modelFile = $databaseModel->getModelClassNameWithNameSpace()->filename;
    file_put_contents($modelFile, $databaseModel->getDoctrineModelCode());
    echo "generated $modelFile\n";
}
